function sumOddLengthSubarrays(arr) {
  const n = arr.length;
  let total = 0;
  for (let i = 0; i < n; i++) {
    // Count starts at an even or odd distance before i, and ends at an even or odd distance after it.
    const leftEven = Math.floor(i / 2) + 1;
    const leftOdd = Math.floor((i + 1) / 2);
    const rightEven = Math.floor((n - 1 - i) / 2) + 1;
    const rightOdd = Math.floor((n - i) / 2);
    // The length (both distances + 1) is odd exactly when the two distances have the same parity.
    const oddCount = leftEven * rightEven + leftOdd * rightOdd;
    total += arr[i] * oddCount;
  }
  return total;
}

